public static byte[] A00(SecretKeySpec secretKeySpec, B7K b7k, B7K b7k2, byte[] bArr, int i) {
    try {
        javax.crypto.Mac mac = javax.crypto.Mac.getInstance(DefaultCrypto.HMAC_SHA256);
        mac.init(secretKeySpec);
        if (i >= 3) {
            mac.update(b7k.A00.A00());
            mac.update(b7k2.A00.A00());
        }
        byte[] bArrDoFinal = mac.doFinal(bArr);
        byte[] bArr2 = new byte[8];
        System.arraycopy(bArrDoFinal, 0, bArr2, 0, 8);
        return bArr2;
    } catch (InvalidKeyException | NoSuchAlgorithmException e) {
        throw Ayj.A14(e);
    }
}
